  App.Data.t4.kimia.pengenalan_kimia = (App.Data.t4.kimia.pengenalan_kimia || []).concat([
    { q: "Apakah fungsi peralatan perlindungan diri (PPE) seperti gogal keselamatan di makmal?", qEn: "What is the purpose of wearing safety goggles in the chemistry lab?", options: ["Melindungi mata daripada percikan bahan kimia dan serpihan kaca", "Membantu melihat atom dengan mata kasar", "Mengelakkan wap air di bilik darjah", "Mengukur ketumpatan cecair"], optionsEn: ["Protect eyes from chemical splashes and shattered glass", "See individual atoms directly", "Block water vapour", "Measure liquid density"], correctIndex: 0, explanation: "Gogal keselamatan melindungi mata daripada percikan asid, alkali atau bahan berbahaya.", explanationEn: "Safety goggles shield eyes from splashes and flying glass." },
    { q: "Bagaimana langkah melupuskan sisa pelarut organik (seperti asetona dan alkohol) dengan selamat?", qEn: "How should organic solvent waste (like acetone and alcohol) be disposed of?", options: ["Dikumpul dalam botol sisa khas berlabel dan dihantar ke pusat pelupusan bertauliah", "Dibuang terus ke dalam singki makmal", "Dituang ke atas rumput luar makmal", "Dibiarkan terdedah di tepi tingkap"], optionsEn: ["Collected in labelled hazardous waste containers for licensed disposal", "Poured down the lab sink", "Poured onto outdoor grass", "Left open by the window"], correctIndex: 0, explanation: "Pelarut organik mudah terbakar dan tidak boleh dibuang ke dalam singki.", explanationEn: "Organic solvents are flammable and must go into labelled waste bottles." },
    { q: "Apakah kepentingan graf dalam kaedah saintifik kimia?", qEn: "Why are graphs important in scientific chemistry investigations?", options: ["Menunjukkan corak hubungan antara pemboleh ubah dengan jelas dan membuat ramalan", "Menggantikan semua eksperimen", "Menyembunyikan kesilapan alat", "Membazirkan masa makmal"], optionsEn: ["Clearly visualise relationships between variables and allow predictions", "Replace all experiments", "Hide instrument errors", "Waste lab time"], correctIndex: 0, explanation: "Graf memudahkan pentafsiran hubungan linear atau berkadar langsung/songsang.", explanationEn: "Graphs reveal trends and relationships between variables." },
    { q: "Apakah peranan ahli kimia dalam bidang perubatan dan farmaseutikal?", qEn: "What is a chemist's role in medicine and pharmaceuticals?", options: ["Menghasilkan ubat-ubatan baharu, antibiotik dan vaksin", "Membaiki enjin kapal terbang", "Melukis pelan jambatan", "Mencetak wang kertas"], optionsEn: ["Developing new medicines, antibiotics, and vaccines", "Repairing plane engines", "Designing bridges", "Printing banknotes"], correctIndex: 0, explanation: "Industri farmaseutikal bergantung pada sintesis kimia dan analisis ubat.", explanationEn: "Chemists synthesise and test pharmaceutical drugs." },
    { q: "Apakah langkah penting sebelum memulakan eksperimen yang melibatkan asid pekat?", qEn: "What precaution is required before handling concentrated acids?", options: ["Memakai sarung tangan tahan kimia, gogal, kot makmal dan bekerja dalam kebuk wasap", "Menggunakan tangan kosong supaya cepat", "Menambah air terus ke dalam asid pekat secara mengejut", "Merasa asid dengan hujung jari"], optionsEn: ["Wear chemical-resistant gloves, goggles, lab coat, and work in a fume hood", "Use bare hands", "Pour water abruptly into concentrated acid", "Taste with a finger"], correctIndex: 0, explanation: "Apabila mencairkan asid pekat, sentiasa tuang asid perlahan-lahan ke dalam air (bukan air ke dalam asid).", explanationEn: "Always use PPE and fume hood; add acid slowly to water." }
  ]);

  App.Data.t4.kimia.bahan_buatan = [
    { q: "Apakah maksud 'aloi' (alloy)?", qEn: "What is an alloy?", options: ["Campuran dua atau lebih unsur dengan unsur utamanya ialah logam", "Logam tulen 100%", "Sebatian bukan logam sahaja", "Plastik sintetik"], optionsEn: ["A mixture of two or more elements where the main element is a metal", "100% pure metal", "Non-metal compound", "Synthetic plastic"], correctIndex: 0, explanation: "Pengaloian memperbaiki sifat logam tulen supaya lebih keras dan tahan kakisan.", explanationEn: "Alloys mix a primary metal with other elements to improve strength/corrosion resistance." },
    { q: "Mengapakah gangsa (aloi kuprum + timah) lebih keras daripada kuprum tulen?", qEn: "Why is bronze harder than pure copper?", options: ["Atom asing yang berbeza saiz mengganggu susunan teratur atom logam dan menghalang lapisan atom daripada menggelongsor", "Atom menjadi lebih kecil", "Tiada ikatan logam", "Kuprum cair pada suhu bilik"], optionsEn: ["Foreign atoms of different sizes disrupt the orderly layers and prevent them from sliding easily", "Atoms shrink", "No metallic bond", "Copper is liquid"], correctIndex: 0, explanation: "Gangguan kekisi atom menghalang gelongsoran apabila dikenakan daya.", explanationEn: "Different-sized atoms block layers from sliding." },
    { q: "Apakah unsur utama yang dicampurkan dengan besi untuk menghasilkan keluli (steel)?", qEn: "What element is mixed with iron to make steel?", options: ["Karbon", "Timah", "Plumbum", "Natrium"], optionsEn: ["Carbon", "Tin", "Lead", "Sodium"], correctIndex: 0, explanation: "Keluli ialah aloi besi dan karbon; keluli nirkarat menambah kromium dan nikel.", explanationEn: "Steel is iron + carbon." },
    { q: "Apakah kegunaan utama kaca borosilikat (seperti Pyrex)?", qEn: "What is borosilicate glass used for?", options: ["Alat radas makmal dan peralatan memasak kerana tahan haba dan pengembangan terma rendah", "Tingkap kereta kalis peluru sahaja", "Beg plastik", "Batu bata"], optionsEn: ["Lab glassware and cookware due to high heat resistance", "Bulletproof windows only", "Plastic bags", "Bricks"], correctIndex: 0, explanation: "Kaca borosilikat mengandungi boron oksida dan tidak mudah retak apabila dipanaskan.", explanationEn: "Low thermal expansion makes it ideal for labware." },
    { q: "Apakah bahan asas utama untuk membuat kaca soda kapur dan seramik tradisional?", qEn: "What is the main raw material for glass vs traditional ceramics?", options: ["Kaca: silika (pasir SiO₂); Seramik: tanah liat (silikat aluminium)", "Kedua-duanya diperbuat daripada plastik", "Kaca daripada besi", "Seramik daripada minyak"], optionsEn: ["Glass: silica (SiO₂); Ceramics: clay (aluminosilicate)", "Both from plastic", "Glass from iron", "Ceramics from oil"], correctIndex: 0, explanation: "Silika ialah komponen utama kaca; tanah liat untuk seramik.", explanationEn: "Silica makes glass; clay makes traditional ceramics." },
    { q: "Apakah komponen utama aloi duralumin dan kegunaannya?", qEn: "What is duralumin made of and where is it used?", options: ["Aluminium dengan kuprum, magnesium dan mangan — ringan dan kuat untuk badan kapal terbang", "Besi dengan karbon — untuk landasan kereta api", "Kuprum dengan zink — untuk alat muzik", "Timah dengan plumbum — untuk pateri"], optionsEn: ["Aluminium with copper, magnesium, manganese — light and strong for aircraft bodies", "Iron and carbon — rails", "Copper and zinc — brass instruments", "Tin and lead — solder"], correctIndex: 0, explanation: "Duralumin mempunyai ketumpatan rendah tetapi kekuatan tinggi, sesuai dalam aeroangkasa.", explanationEn: "Duralumin is lightweight and strong, ideal for aircraft." },
    { q: "Apakah unsur yang ditambah ke dalam keluli untuk menghasilkan keluli nirkarat (stainless steel) yang tahan karat?", qEn: "Which elements are added to make corrosion-resistant stainless steel?", options: ["Kromium dan nikel", "Timah dan zink", "Natrium dan kalium", "Karbon sahaja"], optionsEn: ["Chromium and nickel", "Tin and zinc", "Sodium and potassium", "Carbon only"], correctIndex: 0, explanation: "Kromium membentuk lapisan oksida pelindung yang menghalang besi daripada berkarat.", explanationEn: "Chromium and nickel prevent rusting in stainless steel." },
    { q: "Apakah contoh bahan komposit yang digunakan dalam pembinaan jambatan dan bangunan?", qEn: "Which composite material is widely used in bridges and buildings?", options: ["Konkrit diperkukuh (Reinforced concrete)", "Kaca silika terlakur", "Plastik PVC biasa", "Garam tulen"], optionsEn: ["Reinforced concrete", "Fused silica glass", "Plain PVC plastic", "Pure salt"], correctIndex: 0, explanation: "Konkrit diperkukuh menggabungkan kekuatan mampatan konkrit dengan kekuatan regangan keluli.", explanationEn: "Reinforced concrete combines concrete with steel bars." },
    { q: "Apakah kelebihan seramik termaju (seperti silikon karbida dan alumina) dalam industri?", qEn: "What is an advantage of advanced ceramics?", options: ["Sangat keras, tahan suhu amat tinggi dan tahan kakisan kimia", "Mudah melebur pada 50°C", "Mudah diregangkan seperti getah", "Mengalirkan arus elektrik sangat baik"], optionsEn: ["Very hard, heat-resistant, and chemically inert", "Melts at 50°C", "Stretchy like rubber", "Excellent electrical conductor"], correctIndex: 0, explanation: "Seramik termaju digunakan dalam brek cakera, enjin jet dan gigi palsu.", explanationEn: "Advanced ceramics withstand extreme heat and wear." },
    { q: "Apakah kegunaan gentian optik (bahan komposit kaca/plastik)?", qEn: "What is the main use of optical fibres (a composite material)?", options: ["Penghantaran data dan telekomunikasi berkelajuan tinggi melalui pantulan cahaya", "Membina tiang konkrit", "Menyadur logam besi", "Membuat periuk tanah"], optionsEn: ["High-speed data transmission and telecommunications using light signals", "Building concrete pillars", "Electroplating iron", "Making clay pots"], correctIndex: 0, explanation: "Gentian optik membawa maklumat pada kelajuan tinggi dengan kehilangan isyarat minimum.", explanationEn: "Optical fibres carry light signals rapidly over long distances." }
  ];

