  App.Data.t4.biologi.pengenalan_biologi = [
    { q: "Apakah maksud Biologi?", qEn: "What is Biology?", options: ["Kajian saintifik tentang organisma hidup dan interaksinya dengan persekitaran", "Kajian tentang batuan dan mineral", "Kajian tentang bintang dan planet", "Kajian tentang arus elektrik"], optionsEn: ["Scientific study of living organisms and their interactions with the environment", "Study of rocks", "Study of stars", "Study of electric currents"], correctIndex: 0, explanation: "Perkataan Biologi berasal daripada bahasa Yunani 'bios' (hidup) dan 'logos' (kajian).", explanationEn: "Biology comes from Greek 'bios' (life) and 'logos' (study)." },
    { q: "Apakah fungsi kabinet keselamatan biologi (biological safety cabinet) di makmal?", qEn: "What is the function of a biological safety cabinet?", options: ["Menyediakan ruang kerja tertutup yang selamat apabila mengendalikan patogen atau kultur mikroorganisma", "Menyimpan buku teks", "Memanaskan air minuman", "Menimbang bahan kimia kering sahaja"], optionsEn: ["Provides a safe enclosed workspace when handling pathogens or microbial cultures", "Stores textbooks", "Heats drinking water", "Weighs dry chemicals only"], correctIndex: 0, explanation: "Ia melindungi penyelidik dan persekitaran daripada aerosol berbahaya.", explanationEn: "It protects users from biohazardous aerosols." },
    { q: "Bagaimanakah sisa biologi kategori B (pepejal tidak tajam seperti sarung tangan dan tisu tercemar) dilupuskan?", qEn: "How is Category B biological waste (non-sharp solids like gloves/swabs) disposed of?", options: ["Dimasukkan ke dalam beg plastik biobahaya dan diautoklaf sebelum dibuang", "Dibuang terus ke dalam bakul sampah biasa", "Dibuang ke dalam singki", "Dibakar di atas meja makmal"], optionsEn: ["Placed in biohazard bags and autoclaved before disposal", "Thrown in regular bins", "Flushed down the sink", "Burned on the lab bench"], correctIndex: 0, explanation: "Autoklaf mensterilkan sisa biologi pada suhu dan tekanan tinggi.", explanationEn: "Autoclaving sterilises biohazard waste." },
    { q: "Apakah fungsi kotak khas 'sharps bin' (bekas benda tajam) di makmal biologi?", qEn: "What is the 'sharps bin' used for in a biology lab?", options: ["Membuang sisa kategori A seperti jarum, picagari, skalpel dan kaca pecah", "Menyimpan kanta pembesar", "Membuang kertas kosong", "Menyimpan spesimen hidup"], optionsEn: ["Disposing of Category A sharp waste like needles, scalpels, and broken glass", "Storing magnifying glasses", "Throwing blank paper", "Keeping live specimens"], correctIndex: 0, explanation: "Benda tajam mesti diasingkan dalam bekas kalis bocor untuk mengelakkan kecederaan.", explanationEn: "Sharp biohazard waste goes into puncture-proof sharps bins." },
    { q: "Dalam melukis graf biologi, apakah paksi yang digunakan untuk pemboleh ubah dimanipulasi pada graf?", qEn: "In biological graphs, which axis is used for the manipulated variable?", options: ["Paksi-x (mengufuk)", "Paksi-y (menegak)", "Paksi-z", "Tidak perlu paksi"], optionsEn: ["x-axis (horizontal)", "y-axis (vertical)", "z-axis", "No axis needed"], correctIndex: 0, explanation: "Pemboleh ubah dimanipulasi diplot pada paksi-x; pemboleh ubah bergerak balas pada paksi-y.", explanationEn: "Manipulated variable goes on the x-axis; responding on the y-axis." },
    { q: "Apakah maksud satah sagital (sagittal plane) pada badan organisma?", qEn: "What is a sagittal plane?", options: ["Satah menegak yang membahagikan badan kepada bahagian kiri dan kanan", "Satah yang membahagikan badan kepada atas dan bawah", "Satah yang membahagikan depan dan belakang", "Satah melintang pada kaki"], optionsEn: ["Vertical plane dividing the body into left and right parts", "Divides top and bottom", "Divides front and back", "Horizontal foot plane"], correctIndex: 0, explanation: "Satah sagital (kiri/kanan), satah frontal/koronal (depan/belakang), satah melintang (atas/bawah).", explanationEn: "Sagittal divides left and right." },
    { q: "Bidang biologi yang mengkaji pewarisan ciri dan variasi daripada ibu bapa kepada anak ialah...", qEn: "The branch of biology studying heredity and variation is...", options: ["Genetik", "Ekologi", "Taksonomi", "Fisiologi"], optionsEn: ["Genetics", "Ecology", "Taxonomy", "Physiology"], correctIndex: 0, explanation: "Genetik mengkaji gen, DNA dan pewarisan.", explanationEn: "Genetics studies genes and inheritance." },
    { q: "Apakah langkah pertama jika berlaku tumpahan bahan biologi cecair di atas meja makmal?", qEn: "What is the first step if a liquid biological spill occurs on the lab bench?", options: ["Maklumkan kepada guru dengan segera, tutup tumpahan dengan tisu kertas dan nyahjangkit dengan larutan disinfektan", "Lap dengan tangan kosong", "Biarkan sahaja hingga kering", "Tiup supaya cepat kering"], optionsEn: ["Inform the teacher immediately, cover with paper towels, and disinfect", "Wipe with bare hands", "Leave it to dry", "Blow on it"], correctIndex: 0, explanation: "Prosedur keselamatan makmal mewajibkan laporan segera dan penyahjangkitan.", explanationEn: "Report immediately and disinfect properly." },
    { q: "Apakah maksud satah melintang (transverse / horizontal plane) pada tubuh organisma?", qEn: "What does the transverse (horizontal) plane divide the body into?", options: ["Bahagian atas (superior) dan bahagian bawah (inferior)", "Bahagian kiri dan kanan", "Bahagian hadapan dan belakang", "Bahagian dalam sahaja"], optionsEn: ["Upper (superior) and lower (inferior) parts", "Left and right parts", "Front and back parts", "Inner part only"], correctIndex: 0, explanation: "Satah melintang memotong secara mendatar membahagikan tubuh kepada atas dan bawah.", explanationEn: "Transverse plane divides upper and lower halves." },
    { q: "Bidang biologi yang mengkaji interaksi antara organisma hidup dengan persekitarannya ialah...", qEn: "Which branch of biology studies interactions between organisms and their environment?", options: ["Ekologi", "Anatomi", "Sitologi", "Botani"], optionsEn: ["Ecology", "Anatomy", "Cytology", "Botany"], correctIndex: 0, explanation: "Ekologi mengkaji ekosistem, habitat, rantai makanan dan keseimbangan alam.", explanationEn: "Ecology studies organisms and their environments." }
  ];

  App.Data.t4.biologi.komposisi_kimia = [
    { q: "Mengapakah air (H₂O) dianggap molekul berkutub (polar)?", qEn: "Why is water (H₂O) a polar molecule?", options: ["Atom oksigen lebih elektronegatif, mewujudkan cas separa negatif pada O dan separa positif pada H", "Ia mempunyai cas ion +2", "Ia tidak mempunyai elektron", "Ia berbentuk linear"], optionsEn: ["Oxygen is more electronegative, creating partial negative charge on O and positive on H", "Has +2 charge", "No electrons", "Linear shape"], correctIndex: 0, explanation: "Kekutuban air membolehkan ikatan hidrogen terbentuk dan melarutkan banyak bahan.", explanationEn: "Unequal electron sharing makes water polar." },
    { q: "Apakah monomer bagi karbohidrat kompleks (polisakarida seperti kanji dan glikogen)?", qEn: "What is the monomer of polysaccharides like starch and glycogen?", options: ["Monosakarida (seperti glukosa)", "Asid amino", "Asid lemak dan gliserol", "Nukleotida"], optionsEn: ["Monosaccharides (like glucose)", "Amino acids", "Fatty acids and glycerol", "Nucleotides"], correctIndex: 0, explanation: "Unit asas karbohidrat ialah monosakarida (glukosa).", explanationEn: "Glucose units polymerise into starch/glycogen." },
    { q: "Apakah monomer bagi protein?", qEn: "What is the monomer of proteins?", options: ["Asid amino", "Glukosa", "Gliserol", "Nukleotida"], optionsEn: ["Amino acids", "Glucose", "Glycerol", "Nucleotides"], correctIndex: 0, explanation: "Asid amino dihubungkan oleh ikatan peptida membentuk polipeptida/protein.", explanationEn: "Amino acids link via peptide bonds." },
    { q: "Apakah tiga komponen satu nukleotida dalam DNA/RNA?", qEn: "What are the three components of a nucleotide?", options: ["Gula pentosa, kumpulan fosfat dan bes bernitrogen", "Asid lemak, gliserol dan air", "Glukosa, fruktosa dan sukrosa", "Asid amino sahaja"], optionsEn: ["Pentose sugar, phosphate group, and nitrogenous base", "Fatty acid, glycerol, water", "Glucose, fructose, sucrose", "Amino acids only"], correctIndex: 0, explanation: "DNA mempunyai gula deoksiribosa dan bes A, T, C, G.", explanationEn: "Nucleotides consist of pentose sugar, phosphate, and a nitrogenous base." },
    { q: "Apakah polisakarida simpanan tenaga utama dalam sel haiwan dan manusia?", qEn: "What is the main energy storage polysaccharide in animal cells?", options: ["Glikogen (disimpan di hati dan otot)", "Kanji", "Selulosa", "Kitin"], optionsEn: ["Glycogen (stored in liver and muscles)", "Starch", "Cellulose", "Chitin"], correctIndex: 0, explanation: "Tumbuhan menyimpan kanji; haiwan menyimpan glikogen.", explanationEn: "Animals store glucose as glycogen." },
    { q: "Apakah tiga contoh disakarida dan monomer pembentuknya?", qEn: "What are the three common disaccharides and their constituent monomers?", options: ["Maltosa (glukosa+glukosa), Sukrosa (glukosa+fruktosa) dan Laktosa (glukosa+galaktosa)", "Kanji, glikogen dan selulosa", "Glukosa, fruktosa dan galaktosa sahaja", "Protein dan lipid"], optionsEn: ["Maltose (glu+glu), Sucrose (glu+fru), Lactose (glu+gal)", "Starch, glycogen, cellulose", "Monosaccharides only", "Protein and lipids"], correctIndex: 0, explanation: "Disakarida terbina daripada dua monosakarida melalui proses kondensasi.", explanationEn: "Disaccharides form by condensation of two monosaccharides." },
    { q: "Apakah proses kimia yang menggabungkan dua monosakarida menjadi disakarida dengan menyingkirkan satu molekul air?", qEn: "Which process joins two monosaccharides while removing a water molecule?", options: ["Kondensasi", "Hidrolisis", "Osmosis", "Respirasi"], optionsEn: ["Condensation", "Hydrolysis", "Osmosis", "Respiration"], correctIndex: 0, explanation: "Kondensasi membina molekul besar; hidrolisis memecahkannya menggunakan air.", explanationEn: "Condensation joins monomers and releases water." },
    { q: "Apakah perbezaan antara lemak tepu dan lemak tak tepu?", qEn: "What is the difference between saturated and unsaturated fats?", options: ["Lemak tepu tiada ikatan ganda dua C=C (pepejal pada suhu bilik); lemak tak tepu ada sekurang-kurangnya satu ikatan ganda dua C=C (cecair)", "Lemak tepu adalah cecair", "Lemak tak tepu mengandungi protein", "Tiada perbezaan"], optionsEn: ["Saturated fats have no C=C double bonds (solid at room temp); unsaturated fats have C=C double bonds (liquid)", "Saturated fats are liquid", "Unsaturated fats contain protein", "No difference"], correctIndex: 0, explanation: "Minyak sawit/zaitun mengandungi asid lemak tak tepu; mentega kaya dengan lemak tepu.", explanationEn: "Unsaturated fats contain C=C double bonds and stay liquid." },
    { q: "Apakah jenis lipid utama yang membentuk dwilapisan membran plasma sel?", qEn: "Which lipid forms the bilayer of cell plasma membranes?", options: ["Fosfolipid", "Trigliserida", "Lilin", "Kolesterol tulen sahaja"], optionsEn: ["Phospholipids", "Triglycerides", "Wax", "Cholesterol only"], correctIndex: 0, explanation: "Fosfolipid mempunyai kepala hidrofilik dan dua ekor hidrofobik.", explanationEn: "Phospholipids form the plasma membrane bilayer." },
    { q: "Apakah fungsi utama selulosa dalam tumbuhan?", qEn: "What is the main structural role of cellulose in plants?", options: ["Membentuk dinding sel tumbuhan yang kuat dan memberi sokongan", "Menyimpan tenaga di akar", "Mengangkut gas oksigen", "Membawa kod genetik"], optionsEn: ["Forms rigid plant cell walls providing structural support", "Stores root energy", "Transports oxygen", "Carries genetic code"], correctIndex: 0, explanation: "Dinding sel tumbuhan terdiri daripada gentian selulosa yang tegar.", explanationEn: "Cellulose forms the structural plant cell wall." }
  ];

  App.Data.t4.biologi.metabolisme_enzim = [
    { q: "Apakah maksud 'enzim'?", qEn: "What is an enzyme?", options: ["Pemangkin biologi (protein) yang mempercepatkan tindak balas biokimia tanpa berubah pada akhir tindak balas", "Karbohidrat simpanan", "Lemak tepu", "Vitamin larut air"], optionsEn: ["Biological protein catalyst that speeds up biochemical reactions without being consumed", "Storage carbohydrate", "Saturated fat", "Water-soluble vitamin"], correctIndex: 0, explanation: "Enzim menurunkan tenaga pengaktifan tindak balas dalam sel.", explanationEn: "Enzymes lower activation energy." },
    { q: "Apakah hipotesis yang menerangkan kekhususan tindakan enzim ke atas substrat?", qEn: "Which hypothesis explains enzyme-substrate specificity?", options: ["Hipotesis Mangga dan Kunci (Lock and Key)", "Hipotesis Mozek Bendalir", "Teori Evolusi", "Hukum Snell"], optionsEn: ["Lock and Key Hypothesis", "Fluid Mosaic Model", "Evolution Theory", "Snell's Law"], correctIndex: 0, explanation: "Tapak aktif enzim mempunyai bentuk spesifik yang hanya sepadan dengan substrat tertentu.", explanationEn: "Substrates fit specifically into the enzyme's active site." },
    { q: "Apakah yang berlaku kepada enzim apabila suhu meningkat jauh melebihi suhu optimum (cth: >60°C)?", qEn: "What happens to enzymes at temperatures far above optimum (>60°C)?", options: ["Enzim ternyahasli (denatured) kerana ikatan kimia terputus dan bentuk tapak aktif berubah secara kekal", "Enzim menjadi lebih aktif", "Enzim membeku", "Enzim bertukar menjadi glukosa"], optionsEn: ["Enzymes denature as bonds break and the active site permanently loses its shape", "Become more active", "Freeze", "Turn into glucose"], correctIndex: 0, explanation: "Penyahaslian memusnahkan struktur 3D tapak aktif enzim.", explanationEn: "High heat denatures the active site." },
    { q: "Apakah pH optimum bagi enzim pepsin di dalam perut?", qEn: "What is the optimum pH for pepsin in the stomach?", options: ["pH berasid (~pH 1.5 – 2.0)", "pH 7 (neutral)", "pH 8.5 (beralkali)", "pH 12"], optionsEn: ["Acidic (~pH 1.5 – 2.0)", "pH 7 (neutral)", "pH 8.5 (alkaline)", "pH 12"], correctIndex: 0, explanation: "Pepsin berfungsi optimum dalam persekitaran asid hidroklorik perut.", explanationEn: "Pepsin works best in acidic stomach juice." },
    { q: "Apakah maksud anabolisme berbanding katabolisme?", qEn: "What is anabolism vs catabolism?", options: ["Anabolisme membina molekul kompleks (menyerap tenaga); katabolisme menguraikan molekul kompleks (membebaskan tenaga)", "Kedua-duanya menguraikan makanan", "Anabolisme membebaskan tenaga", "Tiada perbezaan"], optionsEn: ["Anabolism builds complex molecules; catabolism breaks them down", "Both break down food", "Anabolism releases energy", "No difference"], correctIndex: 0, explanation: "Contoh anabolisme: fotosintesis; contoh katabolisme: respirasi sel.", explanationEn: "Anabolism synthesises; catabolism breaks down." },
    { q: "Apakah pH optimum bagi enzim amilase air liur di dalam mulut?", qEn: "What is the optimum pH for salivary amylase in the mouth?", options: ["Sekitar pH 6.5 – 7.5 (neutral)", "pH 1.5", "pH 11", "pH 3.0"], optionsEn: ["Around pH 6.5 – 7.5 (neutral)", "pH 1.5", "pH 11", "pH 3.0"], correctIndex: 0, explanation: "Amilase air liur bertindak paling baik pada keadaan hampir neutral.", explanationEn: "Salivary amylase works best near neutral pH." },
    { q: "Mengapakah enzim yang disejukkan pada suhu 0°C tidak rosak apabila dipanaskan semula ke 37°C?", qEn: "Why can chilled enzymes (0°C) regain activity when warmed back to 37°C?", options: ["Suhu rendah hanya menyahaktifkan enzim buat sementara tanpa merosakkan bentuk tapak aktifnya", "Enzim membina tapak aktif baharu", "Enzim bertukar menjadi lipid", "Suhu rendah menyahasilkan enzim"], optionsEn: ["Low temperature only makes enzymes inactive temporarily without denaturing the active site", "Builds new active sites", "Turns into lipid", "Cold denatures enzymes"], correctIndex: 0, explanation: "Penyahaslian hanya berlaku pada suhu tinggi atau pH ekstrem, bukan suhu sejuk.", explanationEn: "Cold slows kinetic collisions without breaking bonds." },
    { q: "Di organel sel manakah enzim luar sel (seperti pepsin dan amilase) disintesis dan dibungkus sebelum dirembeskan?", qEn: "Which organelles synthesise and package extracellular enzymes before secretion?", options: ["Ribosom -> Jalinan endoplasma kasar -> Jasad Golgi", "Kloroplas -> Vakuol", "Lisosom -> Mitokondrion", "Nukleus -> Dinding sel"], optionsEn: ["Ribosome -> Rough ER -> Golgi apparatus", "Chloroplast -> Vacuole", "Lysosome -> Mitochondrion", "Nucleus -> Cell wall"], correctIndex: 0, explanation: "Enzim ialah protein yang disintesis oleh ribosom pada JE kasar lalu diubah suai di jasad Golgi.", explanationEn: "Ribosomes on RER synthesise proteins, and the Golgi apparatus packages them." },
    { q: "Apakah maksud enzim 'intrasel'?", qEn: "What is an intracellular enzyme?", options: ["Enzim yang disintesis dan bertindak di dalam sel itu sendiri (seperti enzim respirasi dalam mitokondrion)", "Enzim yang dirembeskan keluar ke usus", "Enzim yang terdapat di dalam serbuk pencuci", "Hormon darah"], optionsEn: ["An enzyme synthesised and used inside the same cell", "Secreted into the gut", "Found in washing powder", "Blood hormone"], correctIndex: 0, explanation: "Enzim intrasel kekal di dalam sel; enzim ekstrasel dirembes keluar dari sel.", explanationEn: "Intracellular enzymes function within the cell that produces them." },
    { q: "Apabila kepekatan substrat ditambah berterusan tetapi kepekatan enzim tetap, apakah faktor pengehad kadar tindak balas selepas takat tepu?", qEn: "Once all enzyme active sites are saturated at high substrate concentration, what limits the reaction rate?", options: ["Kepekatan enzim", "Kepekatan substrat", "Isipadu bikar", "Warna substrat"], optionsEn: ["Enzyme concentration", "Substrate concentration", "Beaker size", "Substrate colour"], correctIndex: 0, explanation: "Apabila semua tapak aktif tepu, hanya penambahan enzim dapat meningkatkan kadar.", explanationEn: "At saturation, enzyme concentration is the limiting factor." }
  ];

  App.Data.t4.biologi.respirasi_sel = [
    { q: "Apakah persamaan perkataan bagi respirasi aerob?", qEn: "What is the word equation for aerobic respiration?", options: ["Glukosa + Oksigen -> Karbon dioksida + Air + Tenaga (ATP)", "Karbon dioksida + Air -> Glukosa + Oksigen", "Glukosa -> Asid laktik + Tenaga", "Glukosa -> Etanol + CO₂"], optionsEn: ["Glucose + Oxygen -> Carbon dioxide + Water + Energy (ATP)", "CO₂ + Water -> Glucose + O₂", "Glucose -> Lactic acid + Energy", "Glucose -> Ethanol + CO₂"], correctIndex: 0, explanation: "Respirasi aerob mengoksidakan glukosa sepenuhnya dengan kehadiran oksigen.", explanationEn: "Aerobic respiration completely oxidises glucose using oxygen." },
    { q: "Apakah hasil fermentasi (respirasi anaerob) dalam sel otot manusia semasa senaman cergas?", qEn: "What is produced during anaerobic fermentation in human muscle cells?", options: ["Asid laktik dan sedikit tenaga (2 ATP)", "Etanol dan karbon dioksida", "Oksigen dan air", "Kanji"], optionsEn: ["Lactic acid and a small amount of energy (2 ATP)", "Ethanol and CO₂", "Oxygen and water", "Starch"], correctIndex: 0, explanation: "Pengumpulan asid laktik menyebabkan kelesuan dan kekejangan otot serta hutang oksigen.", explanationEn: "Lactic acid causes muscle fatigue and oxygen debt." },
    { q: "Apakah hasil fermentasi yis dalam keadaan tanpa oksigen?", qEn: "What are the products of yeast fermentation without oxygen?", options: ["Etanol, karbon dioksida dan tenaga (2 ATP)", "Asid laktik sahaja", "Oksigen dan glukosa", "Protein"], optionsEn: ["Ethanol, carbon dioxide, and energy (2 ATP)", "Lactic acid only", "Oxygen and glucose", "Protein"], correctIndex: 0, explanation: "Fermentasi yis digunakan dalam pembuatan roti dan minuman beralkohol.", explanationEn: "Yeast produces ethanol and CO₂." },
    { q: "Berapakah bilangan molekul ATP yang terhasil daripada satu molekul glukosa semasa respirasi aerob berbanding fermentasi?", qEn: "How many ATP molecules are produced per glucose in aerobic respiration vs fermentation?", options: ["~38 ATP (aerob) berbanding 2 ATP (fermentasi)", "2 ATP (aerob) berbanding 38 ATP", "Sama banyak (10 ATP)", "100 ATP"], optionsEn: ["~38 ATP (aerobic) vs 2 ATP (fermentation)", "2 vs 38", "Both 10", "100 ATP"], correctIndex: 0, explanation: "Respirasi aerob menghasilkan tenaga jauh lebih banyak kerana penguraian glukosa lengkap.", explanationEn: "Aerobic respiration yields ~38 ATP per glucose." },
    { q: "Di manakah peringkat glikolisis berlaku dalam sel?", qEn: "Where does glycolysis occur in the cell?", options: ["Sitoplasma", "Nukleus", "Kloroplas", "Ribosom"], optionsEn: ["Cytoplasm", "Nucleus", "Chloroplast", "Ribosome"], correctIndex: 0, explanation: "Glikolisis menguraikan glukosa kepada piruvat di dalam sitoplasma.", explanationEn: "Glycolysis takes place in the cytoplasm." },
    { q: "Apakah maksud 'hutang oksigen' (oxygen debt) selepas larian pecut?", qEn: "What is 'oxygen debt' after intense sprinting?", options: ["Oksigen tambahan yang diperlukan selepas senaman untuk mengoksidakan asid laktik terkumpul di dalam hati", "Kekurangan karbon dioksida dalam darah", "Air yang hilang melalui peluh", "Lemak yang dibakar di otak"], optionsEn: ["Extra oxygen needed after exercise to oxidise accumulated lactic acid in the liver", "Lack of CO₂", "Water lost in sweat", "Fat burned in brain"], correctIndex: 0, explanation: "Bernafas laju dan dalam selepas berhenti berlari membekalkan oksigen untuk menyingkirkan asid laktik.", explanationEn: "Fast breathing supplies oxygen to break down lactic acid." },
    { q: "Di organel manakah peringkat pengoksidaan piruvat dan penghasilan utama ATP bagi respirasi aerob berlaku?", qEn: "Where does the main ATP production stage of aerobic respiration take place?", options: ["Mitokondrion", "Vakuol", "Jasad Golgi", "Ribosom"], optionsEn: ["Mitochondrion", "Vacuole", "Golgi apparatus", "Ribosome"], correctIndex: 0, explanation: "Selepas glikolisis di sitoplasma, piruvat masuk ke dalam mitokondrion.", explanationEn: "Pyruvate enters mitochondria for aerobic oxidation." },
    { q: "Apakah hasil fermentasi alkohol dalam akar tumbuhan padi yang terendam air tanpa oksigen?", qEn: "What does alcoholic fermentation produce in waterlogged paddy plant roots?", options: ["Etanol, karbon dioksida dan sedikit tenaga (2 ATP)", "Asid laktik", "Glikogen", "Oksigen"], optionsEn: ["Ethanol, carbon dioxide, and a small amount of ATP", "Lactic acid", "Glycogen", "Oxygen"], correctIndex: 0, explanation: "Pokok padi mempunyai toleransi tinggi terhadap etanol yang terhasil ketika banjir.", explanationEn: "Waterlogged roots carry out alcoholic fermentation." },
    { q: "Mengapakah asid laktik berbahaya jika dibiarkan terkumpul terlalu banyak dalam otot?", qEn: "Why is excess lactic acid harmful if it builds up in muscle cells?", options: ["Menurunkan pH sel otot dan menyebabkan kekejangan serta kelesuan otot", "Menukarkan otot menjadi tulang", "Meningkatkan oksigen darah", "Menghasilkan klorofil"], optionsEn: ["Lowers cell pH causing muscle fatigue and cramps", "Turns muscle to bone", "Raises blood oxygen", "Makes chlorophyll"], correctIndex: 0, explanation: "Asid laktik dihantar ke hati untuk ditukarkan semula kepada glukosa atau dioksidakan.", explanationEn: "Lactic acid lowers pH and triggers cramps/fatigue." },
    { q: "Apakah pembawa tenaga universal di dalam semua sel hidup?", qEn: "What is the universal energy currency molecule in living cells?", options: ["Adenosina trifosfat (ATP)", "DNA", "Hemoglobin", "Selulosa"], optionsEn: ["Adenosine triphosphate (ATP)", "DNA", "Haemoglobin", "Cellulose"], correctIndex: 0, explanation: "ATP menyimpan tenaga kimia yang mudah dibebaskan melalui hidrolisis kepada ADP + P.", explanationEn: "ATP delivers usable chemical energy for cellular work." }
  ];

  App.Data.t4.biologi.respirasi_haiwan = [
    { q: "Apakah ciri penyesuaian struktur respirasi (seperti alveolus, insang, trakeol) untuk pertukaran gas yang cekap?", qEn: "What adaptations make respiratory surfaces (alveoli, gills, tracheoles) efficient?", options: ["Luas permukaan besar, dinding sangat nipis (setebal satu sel), sentiasa lembap dan kaya dengan kapilari darah", "Dinding tebal dan kering", "Luas permukaan kecil", "Tiada bekalan darah"], optionsEn: ["Large surface area, one-cell-thick walls, moist, and rich blood supply", "Thick and dry", "Small surface area", "No blood supply"], correctIndex: 0, explanation: "Ciri-ciri ini memaksimumkan kadar resapan gas O₂ dan CO₂.", explanationEn: "Maximises gas diffusion rate." },
    { q: "Apakah struktur respirasi bagi serangga seperti belalang?", qEn: "What is the respiratory structure of insects?", options: ["Sistem trakea (trakea dan trakeol melalui spirakel)", "Insang", "Alveolus", "Kulit lembap sahaja"], optionsEn: ["Tracheal system (tracheae and tracheoles via spiracles)", "Gills", "Alveoli", "Moist skin only"], correctIndex: 0, explanation: "Oksigen dihantar terus ke sel melalui trakeol.", explanationEn: "Insects breathe through spiracles and tracheoles." },
    { q: "Semasa menarik nafas (inhalasi) pada manusia, apakah yang berlaku kepada diafragma dan sangkar rusuk?", qEn: "During human inhalation, what happens to the diaphragm and ribcage?", options: ["Diafragma mengecut dan mendatar; sangkar rusuk bergerak ke atas dan ke luar", "Diafragma mengendur dan melengkung ke atas", "Isi padu rongga toraks berkurang", "Tekanan udara dalam peparu meningkat melebihi atmosfera"], optionsEn: ["Diaphragm contracts and flattens; ribcage moves up and out", "Diaphragm relaxes upward", "Thoracic volume decreases", "Lung pressure rises above atmospheric"], correctIndex: 0, explanation: "Isi padu toraks bertambah -> tekanan peparu turun -> udara masuk.", explanationEn: "Thoracic volume increases, lowering pressure so air rushes in." },
    { q: "Apakah fungsi injap bikuspid dan trikuspid dalam jantung manusia?", qEn: "What is the function of heart valves (bicuspid and tricuspid)?", options: ["Memastikan darah mengalir dalam satu arah sahaja dan menghalang pengaliran balik darah", "Mengepam darah ke otak", "Menghasilkan sel darah putih", "Menyerap oksigen"], optionsEn: ["Ensure one-way blood flow and prevent backflow", "Pump blood to brain", "Make white blood cells", "Absorb oxygen"], correctIndex: 0, explanation: "Injap mencegah darah berpatah balik ke atrium apabila ventrikel mengecut.", explanationEn: "Valves prevent backflow of blood." },
    { q: "Apakah salur darah yang mengangkut darah beroksigen dari peparu kembali ke atrium kiri jantung?", qEn: "Which blood vessel carries oxygenated blood from the lungs to the left atrium?", options: ["Vena pulmonari", "Arteri pulmonari", "Aorta", "Vena kava"], optionsEn: ["Pulmonary vein", "Pulmonary artery", "Aorta", "Vena cava"], correctIndex: 0, explanation: "Vena pulmonari ialah satu-satunya vena yang membawa darah beroksigen dalam peredaran darah manusia.", explanationEn: "The pulmonary vein carries oxygenated blood to the left atrium." },
    { q: "Dalam ikan, bagaimanakah pertukaran gas di filamen insang dimaksimumkan?", qEn: "In fish gills, what mechanism maximises oxygen uptake from water?", options: ["Mekanisme aliran bertentangan (countercurrent exchange) antara aliran air dan aliran darah", "Aliran searah tanpa kapilari", "Bernafas melalui paru-paru", "Kulit kering bersisik"], optionsEn: ["Countercurrent exchange between water flow and blood flow", "Same-direction flow", "Breathing via lungs", "Dry scaly skin"], correctIndex: 0, explanation: "Aliran bertentangan mengekalkan kecerunan kepekatan oksigen sepanjang filamen insang.", explanationEn: "Countercurrent flow keeps a favourable diffusion gradient along the gill." },
    { q: "Dalam bentuk apakah kebanyakan karbon dioksida (CO₂) diangkut dalam darah manusia?", qEn: "In what form is most carbon dioxide (CO₂) transported in human blood?", options: ["Sebagai ion bikarbonat (HCO₃⁻) terlarut dalam plasma darah (~70%)", "Terlarut sebagai gas dalam minyak", "Digabung dengan kalsium membentuk tulang", "Disimpan dalam platlet"], optionsEn: ["As bicarbonate ions (HCO₃⁻) dissolved in blood plasma (~70%)", "Dissolved in oil", "Bound to calcium", "Inside platelets"], correctIndex: 0, explanation: "Sekitar 70% CO₂ diangkut sebagai ion bikarbonat, 23% sebagai karbaminohemoglobin dan 7% terlarut dalam plasma.", explanationEn: "Most CO₂ is carried as plasma bicarbonate ions." },
    { q: "Apakah nama alat perentak semula jadi jantung (pacemaker) yang memulakan denyutan jantung pada atrium kanan?", qEn: "What is the heart's natural pacemaker located in the right atrium?", options: ["Nodus sinoatrium (SAN)", "Nodus atrioventrikel (AVN)", "Berkas His", "Gentian Purkinje"], optionsEn: ["Sinoatrial node (SAN)", "Atrioventricular node (AVN)", "Bundle of His", "Purkinje fibres"], correctIndex: 0, explanation: "Nodus SA menjana impuls elektrik yang menyebabkan kedua-dua atrium mengecut serentak.", explanationEn: "The SAN initiates electrical impulses for heart contraction." },
    { q: "Apakah fungsi pembuluh kil (lakteal) di dalam setiap vilus usus kecil?", qEn: "What is the function of the lacteal inside an intestinal villus?", options: ["Menyerap asid lemak, gliserol dan vitamin larut lemak (A, D, E, K)", "Menyerap glukosa dan asid amino terus ke darah", "Menghasilkan enzim amilase", "Mengepam oksigen"], optionsEn: ["Absorbs fatty acids, glycerol, and fat-soluble vitamins (A, D, E, K)", "Absorbs glucose directly", "Produces amylase", "Pumps oxygen"], correctIndex: 0, explanation: "Kapilari darah menyerap glukosa & asid amino; lakteal menyerap hasil pencernaan lipid.", explanationEn: "Lacteals transport absorbed lipids into the lymphatic system." },
    { q: "Apakah perbezaan struktur antara dinding arteri dan dinding vena?", qEn: "How does an artery wall differ from a vein wall?", options: ["Arteri mempunyai dinding berotot tebal dan kenyal tanpa injap (kecuali injap sabit aorta/pulmonari); vena dinding lebih nipis dengan injap di sepanjang laluan", "Vena mempunyai dinding lebih tebal", "Arteri tidak mempunyai tisu otot", "Kedua-duanya berstruktur sama tepat"], optionsEn: ["Arteries have thick elastic muscular walls without valves along length; veins have thinner walls and valves", "Veins have thicker walls", "Arteries have no muscle", "Identical structure"], correctIndex: 0, explanation: "Tekanan darah dalam arteri sangat tinggi, jadi dindingnya tebal dan kenyal.", explanationEn: "High-pressure arteries require thick elastic muscular walls." }
  ];

